const API='https://api.modrinth.com/v2';
const $=id=>document.getElementById(id);
const DL='<svg viewBox="0 0 24 24"><path d="M12 4v11M7 11l5 5 5-5M5 20h14"/></svg>';
let state={q:'',offset:0,loading:false};

function load(reset){
  if(reset){state.offset=0;$('pgrid').innerHTML='<div class="sent" id="sent"></div>';}
  if(state.loading)return;
  state.loading=true;
  $('sent').classList.add('on'); $('sent').textContent='Загружаем...';
  const f=[['project_type:shader']];
  fetch(API+'/search?query='+encodeURIComponent(state.q)+'&facets='+encodeURIComponent(JSON.stringify(f))+'&index=downloads&limit=20&offset='+state.offset)
  .then(r=>r.json()).then(d=>{
    state.loading=false;$('sent').classList.remove('on');$('sent').textContent='';
    $('total').textContent='Найдено: '+d.total_hits;
    d.hits.forEach(h=>renderCard(h));
    state.offset+=d.hits.length;
  });
}

function renderCard(h){
  const c=document.createElement('div'); c.className='card pcard';
  c.innerHTML=`<div class="ph2"><span class="pic" style="background-image:url('${h.icon_url}')"></span><span class="at"><b>${h.title}</b><small>от ${h.author}</small></span></div><p class="pd">${h.description}</p><div class="pf"><span class="stats"><span class="stt">${DL}<i>${h.downloads}</i></span></span><button class="btn pri sm">Скачать</button></div>`;
  c.onclick=()=>openPack(h);
  $('pgrid').insertBefore(c,$('sent'));
}
$('q').oninput=e=>{state.q=e.target.value;load(true)};
$('pgrid').onscroll=e=>{if(e.target.scrollTop+e.target.clientHeight>e.target.scrollHeight-100)load(false)};

let vers=[],dVers;
function DD(root,o){
  root.classList.add('dd');
  root.innerHTML='<button type="button" class="ddb"><span class="ddt"></span></button><ul class="ddm"></ul>';
  const btn=root.children[0],list=root.children[1],txt=btn.children[0];
  function render(){
    list.innerHTML='';
    o.items.forEach(it=>{
      const li=document.createElement('li'); li.className='ddo'+(it.v===o.value?' sel':'');
      li.innerHTML='<span class="ddx"><b>'+it.l+'</b></span>';
      li.onclick=()=>{o.value=it.v;render();root.classList.remove('open');if(o.onChange)o.onChange(it.v)};
      list.appendChild(li);
    });
    const cur=o.items.find(x=>x.v===o.value); txt.textContent=cur?cur.l:'—';
  }
  btn.onclick=e=>{e.stopPropagation();root.classList.toggle('open')};
  document.addEventListener('click',()=>root.classList.remove('open'));
  render();
}

function openPack(h){
  $('dtitle').textContent=h.title; $('dauth').textContent='от '+h.author;
  $('dpd').textContent=h.description; $('dpic').style.backgroundImage=`url('${h.icon_url}')`;
  $('derr').textContent=''; $('dinfo').textContent=''; $('dgo').disabled=true;
  $('dm').classList.add('open');
  $('ddvers').innerHTML='';
  fetch(API+'/project/'+h.project_id+'/version').then(r=>r.json()).then(list=>{
    vers=list;
    const items=vers.map(v=>({v:v.id,l:v.name||v.version_number}));
    DD($('ddvers'),{items:items,value:items[0].v,onChange:()=>checkFile()});
    checkFile();
  });
}
function checkFile(){
  $('dgo').disabled=false;
  const verId=document.querySelector('#ddvers .ddb .ddt').textContent;
  const target=vers.find(v=>(v.name||v.version_number)===verId);
  if(target) $('dinfo').textContent='Файл: '+target.files[0].filename;
}
$('dcancel').onclick=()=>$('dm').classList.remove('open');
$('dgo').onclick=function(){
  const verId=document.querySelector('#ddvers .ddb .ddt').textContent;
  const target=vers.find(v=>(v.name||v.version_number)===verId);
  if(!target)return;
  this.disabled=true; $('gotxt').textContent='Скачиваем...';
  const f=target.files[0];
  if(window.pywebview && window.pywebview.api){
     window.pywebview.api.download_file(f.url, f.filename, 'shaderpacks').then(res=>{
        this.disabled=false;
        if(res&&res.ok){ $('gotxt').textContent='Скачано!'; setTimeout(()=>$('dm').classList.remove('open'),1500); }
        else { $('derr').textContent=res.error; $('gotxt').textContent='Скачать'; }
     });
  } else {
     const a=document.createElement('a'); a.href=f.url; a.download=f.filename; a.click();
     this.disabled=false; $('gotxt').textContent='Скачать';
  }
};
load(true);
